import {RPC,readChainPrice} from './chain-price.mjs';
const $=id=>document.getElementById(id),fmt=x=>Number(x).toLocaleString('en-US',{maximumSignificantDigits:8}),time=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
let id=0,busy=false,paused=false,next=0,last=null,failures=0,backoff=0,points=[];
async function rpc(method,params){const res=await fetch(RPC,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:++id,method,params}),cache:'no-store',signal:AbortSignal.timeout(10000)});if(!res.ok){if(res.status===429){const raw=res.headers.get('Retry-After'),n=Number(raw);backoff=Math.max(backoff,raw&&Number.isFinite(n)?n*1000:60000)}throw Error('链上节点 HTTP '+res.status)}const data=await res.json();if(data.error)throw Error(data.error.message||'节点读取失败');if(!Object.hasOwn(data,'result'))throw Error('节点缺少结果');return data.result;}
function unavailable(message){$('chainPrice').textContent='—';$('chainStatus').textContent=message;$('chainPricePanel').classList.remove('verified');$('chainDetails').textContent=last?'上次成功的区块 #'+last.block+'，时间 '+time(last.timestamp)+'；该旧价格已停止显示。':'不使用聚合器旧价填补。';}
function draw(){if(points.length<2){$('chainChart').textContent='链上采样积累中';return}const vals=points.map(p=>p.price),lo=Math.min(...vals),hi=Math.max(...vals),range=hi-lo||Math.max(hi*.001,1e-12),t0=points[0].timestamp,span=points.at(-1).timestamp-t0||1;let d='';points.forEach((p,i)=>d+=(i===0||p.timestamp-points[i-1].timestamp>30000?'M':'L')+((p.timestamp-t0)/span*280+8).toFixed(1)+','+(64-(p.price-lo)/range*50).toFixed(1)+' ');$('chainChart').innerHTML=`<svg viewBox="0 0 300 80" role="img" aria-label="最近120个已核验链上价格采样"><path d="${d}" fill="none" stroke="#708c78" stroke-width="2"/>${points.map(p=>`<circle cx="${((p.timestamp-t0)/span*280+8).toFixed(1)}" cy="${(64-(p.price-lo)/range*50).toFixed(1)}" r="2" fill="#708c78"><title>区块 ${p.block}：${fmt(p.price)} USDG</title></circle>`).join('')}</svg>`;}
async function refresh(){if(busy||Date.now()<next)return;busy=true;const started=Date.now();$('chainStatus').textContent='正在核验最新区块…';try{const result=await readChainPrice(rpc);last=result;failures=0;backoff=0;$('chainPrice').textContent=fmt(result.price);$('chainStatus').textContent='已读取同一区块的两个池状态';$('chainPricePanel').classList.add('verified');$('chainDetails').textContent='区块 #'+result.block+' · 链上时间 '+time(result.timestamp)+' 北京时间 · '+(Date.now()-started)+'ms';$('chainFormula').textContent=fmt(result.hxPerWolf)+' hXMAX/WOLFPACK × '+fmt(result.usdgPerHx)+' USDG/hXMAX';$('chainBlock').textContent=result.hash;$('chainBlock').href='https://robinhoodchain.blockscout.com/block/'+result.block;if(points.at(-1)?.block!==result.block){points.push(result);points=points.slice(-120);draw()} }catch(err){failures++;backoff=Math.max(backoff,Math.min(60000,1000*2**Math.min(failures,6)));unavailable('链上报价不可用：'+err.message)}finally{busy=false;next=Math.max(started+1000,Date.now()+100,Date.now()+backoff)}}
$('chainPause').onclick=()=>{paused=!paused;$('chainPause').textContent=paused?'恢复链上更新':'暂停链上更新';if(!paused){next=Math.min(next,Date.now()+backoff);refresh()}};
setInterval(()=>{if(last&&Date.now()-last.timestamp>30000)unavailable('区块时间已过期，停止显示价格');if(!paused&&!busy&&Date.now()>=next)refresh();$('chainAge').textContent=last?'距区块时间 '+Math.max(0,Math.floor((Date.now()-last.timestamp)/1000))+'秒 · '+(paused?'更新已暂停':'目标每1秒核验'):'等待链上核验';},250);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!paused)refresh()});refresh();
